SELECT FROM PRODUCT P
AND P.CATEGORY = #{CATID}
AND ( UPPER(P.NAME) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(P.DESCN) LIKE '%' || UPPER(#{keyword}) || '%' )
AND P.PRODUCTID IN
#{pid}
ORDER BY
P.NAME P.CATEGORY, P.NAME P.PRODUCTID
${sortDir}

SELECT , V.QTY FROM ITEM I LEFT JOIN INVENTORY V ON V.ITEMID = I.ITEMID WHERE I.PRODUCTID = #{PRODUCTID}
AND V.QTY > 0
ORDER BY I.ITEMID

mapper.update:
UPDATE INVENTORY
SET QTY = QTY - #{QTY}
WHERE ITEMID = #{ITEMID} AND QTY >= #{QTY}

UPDATE ACCOUNT
EMAIL = #{EMAIL}, FIRSTNAME = #{FIRSTNAME}, LASTNAME = #{LASTNAME}, STATUS = #{STATUS},
WHERE USERID = #{USERID}

mapper.select:
SELECT ORDERID, USERID, ORDERDATE, TOTALPRICE, STATUS
FROM ORDERS


    AND USERID = #{USERID}


    AND STATUS = #{STATUS}


ORDER BY ORDERID DESC
